import React from 'react';
import './EstiloPrincipal.css';
import cafeImg from '../imagenes/Deus_Coffee.png'; // Reusing existing image as placeholder
import { useNavigate } from 'react-router-dom';

const MOCK_PRODUCTS = [
    { id: 1, name: 'Café Especial', price: '4.50€', img: cafeImg },
    { id: 2, name: 'Capuchino', price: '3.50€', img: cafeImg },
    { id: 3, name: 'Latte Macchiato', price: '3.80€', img: cafeImg },
    { id: 4, name: 'Espresso', price: '2.00€', img: cafeImg },
    { id: 5, name: 'Mocha', price: '4.00€', img: cafeImg },
    { id: 6, name: 'Americano', price: '2.50€', img: cafeImg },
];

function PaginaPrincipal() {
    const navigate = useNavigate();

    const handleBack = () => {
        navigate('/');
    };

    return (
        <div className="principal-container">
            <header className="header-principal">
                <h1 className="header-title">Nuestros Productos</h1>
                <button
                    onClick={handleBack}
                    style={{
                        position: 'absolute',
                        left: '20px',
                        top: '25px',
                        background: 'transparent',
                        border: '2px solid white',
                        color: 'white',
                        padding: '5px 15px',
                        borderRadius: '5px',
                        cursor: 'pointer'
                    }}
                >
                    Volver
                </button>
            </header>

            <main className="products-grid">
                {MOCK_PRODUCTS.map((product) => (
                    <div key={product.id} className="product-card">
                        <img src={product.img} alt={product.name} className="product-image" />
                        <div className="product-info">
                            <h3 className="product-name">{product.name}</h3>
                            <p className="product-price">{product.price}</p>
                            <button className="btn-buy">Añadir</button>
                        </div>
                    </div>
                ))}
            </main>

            <footer className="footer-principal">
                <div>© IES José Zerpa - Cafetería</div>
            </footer>
        </div>
    );
}

export default PaginaPrincipal;
